<?php
declare(strict_types=1); require __DIR__.'/../config/auth.php'; require __DIR__.'/../config/database.php'; require __DIR__.'/../config/product_types.php'; require_admin(); if(empty($_SESSION['admin_csrf']))$_SESSION['admin_csrf']=bin2hex(random_bytes(32));seed_product_type_catalog();$msg='';$err='';if($_SERVER['REQUEST_METHOD']==='POST'){if(!hash_equals($_SESSION['admin_csrf'],(string)($_POST['csrf']??'')))$err='Güvenlik doğrulaması geçersiz.';else{try{$stepNames=is_array($_POST['steps']??null)?array_values(array_filter(array_map(fn($s)=>trim((string)$s),$_POST['steps']),fn($s)=>$s!=='')):[];$stepTargets=is_array($_POST['step_targets']??null)?array_values(array_map(fn($s)=>trim((string)$s),$_POST['step_targets'])):[];$fields=json_decode((string)$_POST['fields'],true);if(!$stepNames||!is_array($fields))throw new RuntimeException('En az bir adım gerekli; alanlar geçerli JSON olmalıdır.');$targets=[];foreach($stepNames as $i=>$n)$targets[]=(string)($stepTargets[$i]??'');db()->prepare('UPDATE product_type_catalog SET label=?,unit=?,steps=?::jsonb,fields=?::jsonb,step_targets=?::jsonb,room_setup=?,hint=?,is_active=?,sort_order=?,updated_at=now() WHERE code=?')->execute([trim((string)$_POST['label']),trim((string)$_POST['unit']),json_encode($stepNames,JSON_UNESCAPED_UNICODE),json_encode($fields,JSON_UNESCAPED_UNICODE),json_encode($targets,JSON_UNESCAPED_UNICODE),isset($_POST['room_setup']),trim((string)$_POST['hint']),isset($_POST['is_active']),(int)$_POST['sort_order'],$_POST['code']]);$msg='Şablon kaydedildi.';}catch(Throwable $e){$err=$e->getMessage();}}}$rows=db()->query('SELECT * FROM product_type_catalog ORDER BY sort_order,code')->fetchAll();?><!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ürün şablonları</title><style>body{font-family:Arial;background:#f7f7f2;color:#10211f;margin:0}.w{width:min(1000px,calc(100% - 30px));margin:35px auto}.c{background:#fff;border:1px solid #ddd;padding:18px;margin:16px 0}.f{display:grid;gap:9px}.r{display:grid;grid-template-columns:1fr 1fr 100px;gap:9px}input,textarea,button{padding:9px;font:inherit;border:1px solid #ddd}textarea{min-height:100px;font-family:monospace}button{background:#10211f;color:#fff;font-weight:bold}.ok{background:#e6f8c7;padding:9px}.er{background:#ffe2de;padding:9px}.steps-editor{display:grid;gap:7px}.step-row{display:grid;grid-template-columns:auto 1fr 190px 34px 34px 34px;gap:7px;align-items:center}.step-row input,.step-row select{padding:8px;border:1px solid #ccc;font:inherit}.step-grip{cursor:grab;color:#8a9aa0;font-size:16px;user-select:none;text-align:center}.step-mv{background:#1f4e6e;border:none;color:#fff;font-weight:bold;cursor:pointer;padding:8px;line-height:1}.step-mv:disabled{opacity:.35;cursor:default}.step-mv:not(:disabled):hover{background:#174a72}.step-row.dragging{opacity:.45;outline:2px dashed #1f4e6e}.step-row.drag-over{outline:2px solid #1f4e6e;background:#eef4fb}.step-del{background:#b0301a;border:none;color:#fff;font-weight:bold;cursor:pointer}.step-add{background:#1f4e6e;border:none;color:#fff;font-weight:bold;cursor:pointer;margin-top:6px}</style></head><body><main class="w"><a href="/nexustraveltech/admin/kontrol-merkezi">← Kontrol merkezi</a><h1>Ürün türleri ve form şablonları</h1><p>Bu ekran, tedarikçi ilan formundaki adımlar ve alanları veritabanından yönetir.</p><?php if($msg):?><p class="ok"><?=htmlspecialchars($msg)?></p><?php endif;?><?php if($err):?><p class="er"><?=htmlspecialchars($err)?></p><?php endif;?><?php foreach($rows as $x):?><form class="c f" method="post"><input type="hidden" name="csrf" value="<?=htmlspecialchars($_SESSION['admin_csrf'])?>"><input type="hidden" name="code" value="<?=htmlspecialchars($x['code'])?>"><h2><?=htmlspecialchars($x['code'])?></h2><div class="r"><input name="label" value="<?=htmlspecialchars($x['label'])?>"><input name="unit" value="<?=htmlspecialchars($x['unit'])?>"><input name="sort_order" type="number" value="<?=$x['sort_order']?>"></div><input name="hint" value="<?=htmlspecialchars($x['hint'])?>"><label>Kurulum adımları (her satır: ad + hedef bölüm çapası)<div id="steps-<?=htmlspecialchars($x['code'])?>" class="steps-editor" data-code="<?=htmlspecialchars($x['code'])?>"><?php $sList=json_decode((string)$x['steps'],true)?:[];$tList=json_decode((string)$x['step_targets'],true)?:[];foreach($sList as $si=>$sName):?><div class="step-row" draggable="true"><span class="step-grip" title="Sürükleyerek sırala">⠿</span><input name="steps[]" value="<?=htmlspecialchars((string)$sName)?>" placeholder="Adım adı"><select name="step_targets[]"><option value="">Bölüm yok</option><?php foreach(['sec-01'=>'Temel bilgiler','sec-02'=>'Oda / birim','sec-04'=>'Envanter & fiyat','sec-05'=>'Görseller'] as $v=>$l):?><option value="<?=$v?>" <?=($tList[$si]??'')===$v?'selected':''?>><?=$l?> (<?=$v?>)</option><?php endforeach;?></select><button type="button" class="step-mv" data-dir="up" title="Yukarı taşı">↑</button><button type="button" class="step-mv" data-dir="down" title="Aşağı taşı">↓</button><button type="button" class="step-del" onclick="this.parentElement.remove()">×</button></div><?php endforeach;?></div><button type="button" class="step-add" onclick="var c=document.getElementById('steps-<?=htmlspecialchars($x['code'])?>');var d=document.createElement('div');d.className='step-row';d.innerHTML='<span class=\"step-grip\" title=\"Sürükleyerek sırala\">⠿</span><input name=\"steps[]\" placeholder=\"Adım adı\"><select name=\"step_targets[]\"><option value=\"\">Bölüm yok</option><option value=\"sec-01\">Temel bilgiler (sec-01)</option><option value=\"sec-02\">Oda / birim (sec-02)</option><option value=\"sec-04\">Envanter & fiyat (sec-04)</option><option value=\"sec-05\">Görseller (sec-05)</option></select><button type=\"button\" class=\"step-mv\" data-dir=\"up\" title=\"Yukarı taşı\">↑</button><button type=\"button\" class=\"step-mv\" data-dir=\"down\" title=\"Aşağı taşı\">↓</button><button type=\"button\" class=\"step-del\" onclick=\"this.parentElement.remove()\">×</button>';d.draggable=true;c.appendChild(d);window.nexusStepsRefresh&&nexusStepsRefresh(c)">+ Adım ekle</button></label><label>Alanlar (JSON)<textarea name="fields"><?=htmlspecialchars($x['fields'])?></textarea></label><label><input type="checkbox" name="room_setup" <?=$x['room_setup']?'checked':''?>> Oda/villa kurulumu</label><label><input type="checkbox" name="is_active" <?=$x['is_active']?'checked':''?>> Aktif</label><button>Kaydet</button></form><?php endforeach;?></main><?php require_once __DIR__.'/../config/ai_widget.php'; ai_widget('/nexustraveltech/admin/ai-chat','admin_csrf'); ?><script>window.nexusStepsRefresh=function(wrap){var rows=wrap.querySelectorAll('.step-row');rows.forEach(function(r,i){var u=r.querySelector('.step-mv[data-dir="up"]'),d=r.querySelector('.step-mv[data-dir="down"]');if(u)u.disabled=i===0;if(d)d.disabled=i===rows.length-1;})};document.addEventListener('click',function(e){var mv=e.target.closest?e.target.closest('.step-mv'):null;if(mv){e.preventDefault();var wrap=mv.closest('.steps-editor');if(!wrap)return;var row=mv.closest('.step-row'),dir=mv.getAttribute('data-dir'),sib=dir==='up'?row.previousElementSibling:row.nextElementSibling;if(!sib)return;if(dir==='up')wrap.insertBefore(row,sib);else wrap.insertBefore(sib,row);window.nexusStepsRefresh(wrap);return;}var dl=e.target.closest?e.target.closest('.step-del'):null;if(dl){var w2=dl.closest('.steps-editor');if(w2)window.nexusStepsRefresh(w2);}});document.addEventListener('dragstart',function(e){var t=e.target;if(t.closest&&t.closest('button,input,select,textarea'))return;var row=t.closest?t.closest('.step-row'):null;if(!row)return;row.classList.add('dragging');try{e.dataTransfer.setData('text/plain','step')}catch(err){}});document.addEventListener('dragend',function(e){var row=e.target.closest?e.target.closest('.step-row'):null;if(row){row.classList.remove('dragging');var w=row.closest('.steps-editor');if(w)w.querySelectorAll('.step-row').forEach(function(r){r.classList.remove('drag-over')});}});document.addEventListener('dragover',function(e){var row=e.target.closest?e.target.closest('.step-row'):null;if(!row)return;e.preventDefault();var w=row.closest('.steps-editor');if(!w)return;w.querySelectorAll('.step-row').forEach(function(r){r.classList.remove('drag-over')});row.classList.add('drag-over');try{e.dataTransfer.dropEffect='move'}catch(err){}});document.addEventListener('drop',function(e){e.preventDefault();var row=e.target.closest?e.target.closest('.step-row'):null;if(!row)return;var w=row.closest('.steps-editor');if(!w)return;var from=w.querySelector('.step-row.dragging');if(!from||from===row)return;var rows=Array.prototype.slice.call(w.querySelectorAll('.step-row'));w.insertBefore(from,rows[rows.indexOf(row)+1]||null);w.querySelectorAll('.step-row').forEach(function(r){r.classList.remove('drag-over')});window.nexusStepsRefresh(w);});document.querySelectorAll('.steps-editor').forEach(window.nexusStepsRefresh);</script></body></html>
